-- ----------------------------
-- Table structure for ai_detection_record
-- ----------------------------
DROP TABLE IF EXISTS `ai_detection_record`;
CREATE TABLE `ai_detection_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '检测记录ID',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `detection_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测类型: SENSITIVE_WORD/TYPO/POLICY_REVIEW/FORMAT_CHECK',
  `content_snapshot` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '检测内容快照',
  `result` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '检测结果(JSON)',
  `status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'PENDING' COMMENT '状态: PENDING/PROCESSING/COMPLETED/FAILED/AI_UNAVAILABLE/SKIPPED',
  `task_id` bigint NULL DEFAULT NULL COMMENT '关联的AI任务ID',
  `policy_file_ids` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '关联的政策文件ID列表(逗号分隔)',
  `started_at` datetime NULL DEFAULT NULL COMMENT '开始时间',
  `completed_at` datetime NULL DEFAULT NULL COMMENT '完成时间',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `create_id` bigint NOT NULL DEFAULT 0 COMMENT '创建人ID',
  `create_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建人名称',
  `modify_time` datetime NOT NULL COMMENT '修改时间',
  `modify_id` bigint NOT NULL DEFAULT 0 COMMENT '修改人ID',
  `modify_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '修改人名称',
  `ver` int NOT NULL DEFAULT 1 COMMENT '乐观锁版本号',
  `is_delete` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除: 0-未删除 1-已删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_project`(`project_id` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_detection_type`(`detection_type` ASC) USING BTREE,
  INDEX `idx_task_id`(`task_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '检测记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ai_detection_record
-- ----------------------------

-- ----------------------------
-- Table structure for ai_knowledge_document
-- ----------------------------
DROP TABLE IF EXISTS `ai_knowledge_document`;
CREATE TABLE `ai_knowledge_document`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '文档ID',
  `doc_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '文档名称',
  `doc_category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '文档类别: POLICY(政策文件)/HISTORY_TEMPLATE(历史模板)/STANDARD(标准规范)/OTHER',
  `file_id` bigint NOT NULL COMMENT '文件ID(关联file_info表)',
  `file_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '文件类型: DOC/DOCX/PDF/TXT/MD',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '文档文本内容(解析后的纯文本)',
  `vector_collection` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '向量集合名称(Milvus collection)',
  `vector_ids` json NULL COMMENT '向量ID列表(关联Milvus中的向量)',
  `status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'ACTIVE' COMMENT '状态: ACTIVE/ARCHIVED/PROCESSING/FAILED',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `create_id` bigint NOT NULL DEFAULT 0 COMMENT '创建人ID',
  `create_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '创建人名称',
  `modify_time` datetime NOT NULL COMMENT '修改时间',
  `modify_id` bigint NOT NULL DEFAULT 0 COMMENT '修改人ID',
  `modify_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '修改人名称',
  `ver` int NOT NULL DEFAULT 1 COMMENT '乐观锁版本号',
  `is_delete` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除: 0-未删除, 1-已删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_category`(`doc_category` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_file_id`(`file_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '知识库文档表' ROW_FORMAT = Dynamic;

