  `model_params` json NULL COMMENT '模型参数(temperature/maxTokens/topP/model等)',
  `usage_scenario` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '使用场景: GENERATION/OPTIMIZATION/DETECTION',
  `is_active` tinyint NOT NULL DEFAULT 1 COMMENT '是否启用: 0-停用, 1-启用',
  `token_usage` bigint NOT NULL DEFAULT 0 COMMENT 'Token使用量(累计)',
  `cost` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '累计费用(元)',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `create_id` bigint NOT NULL DEFAULT 0 COMMENT '创建人ID',
  `create_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '创建人名称',
  `modify_time` datetime NOT NULL COMMENT '修改时间',
  `modify_id` bigint NOT NULL DEFAULT 0 COMMENT '修改人ID',
  `modify_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '修改人名称',
  `ver` int NOT NULL DEFAULT 1 COMMENT '乐观锁版本号',
  `is_delete` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除: 0-未删除, 1-已删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_model_type`(`model_type` ASC) USING BTREE,
  INDEX `idx_usage_scenario`(`usage_scenario` ASC) USING BTREE,
  INDEX `idx_is_active`(`is_active` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'AI模型配置表' ROW_FORMAT = Dynamic;

