-- ----------------------------
-- Table structure for ai_project
-- ----------------------------
DROP TABLE IF EXISTS `ai_project`;
CREATE TABLE `ai_project`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '项目ID',
  `project_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '项目编号',
  `project_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '项目名称',
  `project_category` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '项目类别: LIMITED_BELOW/PROPERTY_TRADE/GOVERNMENT_PROCUREMENT',
  `project_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '项目类型: ENGINEERING/GOODS/SERVICE',
  `service_sub_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '服务子类型(当project_type=SERVICE时)',
  `budget` decimal(15, 2) NULL DEFAULT NULL COMMENT '预算金额(元)',
  `project_description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '项目基本情况描述',
  `tender_unit` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '招标单位',
  `project_location` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '项目地点',
  `contact_person` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系人',
  `contact_phone` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系电话',
  `expected_publish_time` datetime NULL DEFAULT NULL COMMENT '预期发布时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `review_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '评审类型: MANUAL/INTELLIGENT',
  `status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'DRAFT' COMMENT '项目状态: DRAFT/IN_PROGRESS/PENDING_DETECTION/DETECTING/DETECTION_PASSED/DETECTION_FAILED/DETECTION_SKIPPED/PUBLISHED/ARCHIVED/CANCELLED',
  `current_phase` int NULL DEFAULT NULL COMMENT '当前编制阶段: 1-基础信息 2-招标需求 3-评审项 4-文档集成 5-智能检测',
  `progress` int NULL DEFAULT NULL COMMENT '完成进度(百分比 0-100)',
  `template_id` bigint NULL DEFAULT NULL COMMENT '使用的模板ID',
  `requirement_id` bigint NULL DEFAULT NULL COMMENT '关联的业务需求ID',
  `requirement_source` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '需求来源: REFERENCE/SYSTEM_GENERATE',
  `requirement_content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '招标需求内容',
  `generated_file_id` bigint NULL DEFAULT NULL COMMENT '生成的招标文件ID(关联file_info)',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `create_id` bigint NOT NULL DEFAULT 0 COMMENT '创建人ID',
  `create_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建人名称',
  `modify_time` datetime NOT NULL COMMENT '修改时间',
  `modify_id` bigint NOT NULL DEFAULT 0 COMMENT '修改人ID',
  `modify_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '修改人名称',
  `ver` int NOT NULL DEFAULT 1 COMMENT '乐观锁版本号',
  `is_delete` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除: 0-未删除 1-已删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_project_code`(`project_code` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_category`(`project_category` ASC) USING BTREE,
  INDEX `idx_create_id`(`create_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'AI编制项目表' ROW_FORMAT = Dynamic;

