INSERT INTO `sup_access_log` VALUES (140, 'eb55f002affe4816824682514f18109e', 'ele-ai-tender-support', 'HTTP_IN', 'GET', '/swagger-ui/swagger-initializer.js', '127.0.0.1', 200, 1, 35, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{}', NULL, 'window.onload = function() {\n  //<editor-fold desc=\"Changeable Configuration Block\">\n\n  // the following lines will be replaced by docker/configurator, when it runs in a docker-container\n  window.ui = SwaggerUIBundle({\n    url: \"https://petstore.swagger.io/v2/swagger.json\",\n    dom_id: \'#swagger-ui\',\n    deepLinking: true,\n    presets: [\n      SwaggerUIBundle.presets.apis,\n      SwaggerUIStandalonePreset\n    ],\n    plugins: [\n      SwaggerUIBundle.plugins.DownloadUrl\n    ],\n    layout: \"StandaloneLayout\" ,\n\r\n  \"configUrl\" : \"/v3/api-docs/swagger-config\",\r\n  \"validatorUrl\" : \"\"\r\n\n  });\n\n  //</editor-fold>\n};\n', NULL, NULL, '2026-04-15 11:24:10');
INSERT INTO `sup_access_log` VALUES (141, 'ed7f9db346f54c04b1d3032d8bda7a0c', 'ele-ai-tender-support', 'HTTP_IN', 'GET', '/v3/api-docs/swagger-config', '127.0.0.1', 200, 1, 2, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{}', NULL, '{\"configUrl\":\"/v3/api-docs/swagger-config\",\"oauth2RedirectUrl\":\"http://127.0.0.1:8080/swagger-ui/oauth2-redirect.html\",\"url\":\"/v3/api-docs\",\"validatorUrl\":\"\"}', NULL, NULL, '2026-04-15 11:24:11');
