INSERT INTO `sup_access_log` VALUES (169, '9fa92181fd7443ab82d6ede1d861b216', 'ele-ai-tender-support', 'HTTP_IN', 'GET', '/v3/api-docs', '127.0.0.1', 200, 1, 6, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{}', NULL, '{\"openapi\":\"3.0.1\",\"info\":{\"title\":\"EleAITender 支撑中心 API\",\"description\":\"支撑中心服务接口文档\",\"contact\":{\"name\":\"EleAITender\"},\"version\":\"1.0.0\"},\"servers\":[{\"url\":\"http://127.0.0.1:8080\",\"description\":\"Generated server url\"}],\"paths\":{\"/api/versions/{id}\":{\"get\":{\"tags\":[\"版本管理\"],\"summary\":\"获取版本详情\",\"operationId\":\"getById\",\"parameters\":[{\"name\":\"id\",\"in\":\"path\",\"required\":true,\"schema\":{\"type\":\"integer\",\"format\":\"int64\"}}],\"responses\":{\"200\":{\"description\":\"OK\",\"content\":{\"*/*\":{\"schema\":{\"$ref\":\"#/components/schemas/ResultSysMainVersion\"}}}}}},\"put\":{\"tags\":[\"版本管理\"],\"summary\":\"更新版本\",\"operationId\":\"update\",\"parameters\":[{\"name\":\"id\",\"in\":\"path\",\"required\":true,\"schema\":{\"type\":\"integer\",\"format\":\"int64\"}}],\"requestBody\":{\"content\":{\"application/json\":{\"schema\":{\"$ref\":\"#/components/schemas/SysMainVersion\"}}},\"required\":true},\"responses\":{\"200\":{\"description\":\"OK\",\"content\":{\"*/*\":{\"schema\":{\"$ref\":\"#/components/schemas/ResultVoid\"}}}}}},\"delete\":{\"tags\":[\"版本管理\"],\"summary\":\"删除版本\",\"operationId\":\"delete\",\"parameters\":[{\"name\":\"id\",\"in\":\"path\",\"required\":true,\"schema\":{\"type\":\"integer\",\"format\":\"int64\"}}],\"responses\":{\"200\":{\"description\":\"OK\",\"content\":{\"*/*\":{\"schema\":{\"$ref\":\"#/components/schemas/ResultVoid\"}}}}}}},\"/api/versions/plugins/{id}\":{\"put\":{\"tags\":[\"版本管理\"],\"summary\":\"更新插件\",\"operationId\":\"updatePlugin\",\"parameters\":[{\"name\":\"id\",\"in\":\"path\",\"required\":true,\"schema\":{\"type\":\"integer\",\"format\":\"int64\"}}],\"requestBody\":{\"content\":{\"application/json\":{\"schema\":{\"$ref\":\"#/