-- ----------------------------
-- Table structure for sup_message
-- ----------------------------
DROP TABLE IF EXISTS `sup_message`;
CREATE TABLE `sup_message`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL COMMENT '接收用户ID',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '消息标题',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '消息内容',
  `message_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '消息类型:SYSTEM(系统)/AUDIT(审核)/DETECTION(检测)/WARNING(警告)',
  `biz_id` bigint NULL DEFAULT NULL COMMENT '关联业务ID(如项目ID、需求ID等)',
  `biz_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '关联业务类型:PROJECT/REQUIREMENT/DETECTION/TEMPLATE',
  `is_read` tinyint(1) NULL DEFAULT 0 COMMENT '是否已读:0未读/1已读',
  `read_time` datetime NULL DEFAULT NULL COMMENT '阅读时间',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `create_id` bigint NULL DEFAULT NULL COMMENT '创建人ID',
  `create_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人名称',
  `modify_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `modify_id` bigint NULL DEFAULT NULL COMMENT '修改人ID',
  `modify_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '修改人名称',
  `ver` int NULL DEFAULT 0 COMMENT '乐观锁版本号',
  `is_delete` int NULL DEFAULT 0 COMMENT '逻辑删除:0未删除/1已删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user`(`user_id` ASC) USING BTREE,
  INDEX `idx_type`(`message_type` ASC) USING BTREE,
  INDEX `idx_read`(`is_read` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '消息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sup_message
-- ----------------------------

-- ----------------------------
-- Table structure for sup_model_route_rule
-- ----------------------------
DROP TABLE IF EXISTS `sup_model_route_rule`;
CREATE TABLE `sup_model_route_rule`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `usage_scenario` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '使用场景: GENERATION/OPTIMIZATION/DETECTION',
  `primary_model_id` bigint NOT NULL COMMENT '优先模型ID(关联ai_model_config.id)',
  `fallback_model_id` bigint NULL DEFAULT NULL COMMENT '降级模型ID(关联ai_model_config.id)',
  `priority` int NOT NULL DEFAULT 0 COMMENT '优先级(值越小优先级越高)',
  `is_active` tinyint NOT NULL DEFAULT 1 COMMENT '是否启用: 0-停用, 1-启用',
  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '规则描述',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `create_id` bigint NOT NULL DEFAULT 0 COMMENT '创建人ID',
  `create_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '创建人名称',
  `modify_time` datetime NOT NULL COMMENT '修改时间',
  `modify_id` bigint NOT NULL DEFAULT 0 COMMENT '修改人ID',
  `modify_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '修改人名称',
  `ver` int NOT NULL DEFAULT 1 COMMENT '乐观锁版本号',
  `is_delete` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除: 0-未删除, 1-已删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_usage_scenario`(`usage_scenario` ASC) USING BTREE,
  INDEX `idx_is_active`(`is_active` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '模型路由规则表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sup_model_route_rule
-- ----------------------------

-- ----------------------------
-- Table structure for sup_operation_log
-- ----------------------------
DROP TABLE IF EXISTS `sup_operation_log`;
CREATE TABLE `sup_operation_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint NULL DEFAULT NULL COMMENT '操作用户ID',
  `user_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '操作用户名',
  `operation` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '操作类型',
  `method` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '请求方法',
  `params` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '请求参数',
  `ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'IP地址',
  `execute_time` bigint NULL DEFAULT NULL COMMENT '执行时长(毫秒)',
  `create_time` datetime NOT NULL COMMENT '操作时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '操作日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sup_operation_log
-- ----------------------------

-- ----------------------------
-- Table structure for sup_plugin_version
-- ----------------------------
DROP TABLE IF EXISTS `sup_plugin_version`;
CREATE TABLE `sup_plugin_version`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '插件版本ID',
  `plugin_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '插件名称',
  `version_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '版本号',
  `compatible_main_version` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '适配的主系统版本',
  `file_id` bigint NOT NULL COMMENT '文件ID',
  `release_notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '发布说明',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态: 0-草稿, 1-已发布, 2-已下线',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `create_id` bigint NOT NULL DEFAULT 0 COMMENT '创建人ID',
  `create_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '创建人名称',
  `modify_time` datetime NOT NULL COMMENT '修改时间',
  `modify_id` bigint NOT NULL DEFAULT 0 COMMENT '修改人ID',
  `modify_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '修改人名称',
  `ver` int NOT NULL DEFAULT 1 COMMENT '乐观锁版本号',
  `is_delete` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除: 0-未删除, 1-已删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_plugin_version`(`plugin_name` ASC, `version_number` ASC) USING BTREE,
  INDEX `idx_compatible_version`(`compatible_main_version` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '插件版本表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sup_plugin_version
-- ----------------------------

-- ----------------------------
-- Table structure for sup_policy_file
-- ----------------------------
DROP TABLE IF EXISTS `sup_policy_file`;
CREATE TABLE `sup_policy_file`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `file_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '文件名称',
  `file_category` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '文件分类: LAW(法律法规)/REGULATION(规章制度)/POLICY(政策文件)',
  `applicable_category` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '适用项目类别: LIMITED_BELOW/PROPERTY_TRADE/GOVERNMENT_PROCUREMENT',
  `file_id` bigint NULL DEFAULT NULL COMMENT '关联文件服务的file_id',
  `file_size` bigint NULL DEFAULT NULL COMMENT '文件大小(字节)',
  `file_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '文件格式: PDF/DOCX/DOC/XLSX',
  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '文件描述',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态: 0-禁用, 1-启用',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `create_id` bigint NOT NULL DEFAULT 0 COMMENT '创建人ID',
  `create_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '创建人名称',
  `modify_time` datetime NOT NULL COMMENT '修改时间',
  `modify_id` bigint NOT NULL DEFAULT 0 COMMENT '修改人ID',
  `modify_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '修改人名称',
  `ver` int NOT NULL DEFAULT 1 COMMENT '乐观锁版本号',
  `is_delete` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除: 0-未删除, 1-已删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_file_category`(`file_category` ASC) USING BTREE,
  INDEX `idx_applicable_category`(`applicable_category` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '系统政策文件表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sup_policy_file
-- ----------------------------

-- ----------------------------
-- Table structure for sup_role
-- ----------------------------
DROP TABLE IF EXISTS `sup_role`;
CREATE TABLE `sup_role`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '角色ID',
  `role_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '角色编码',
  `role_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '角色名称',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '角色描述',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态: 0-禁用, 1-启用',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `create_id` bigint NOT NULL DEFAULT 0 COMMENT '创建人ID',
  `create_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '创建人名称',
  `modify_time` datetime NOT NULL COMMENT '修改时间',
  `modify_id` bigint NOT NULL DEFAULT 0 COMMENT '修改人ID',
  `modify_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '修改人名称',
  `ver` int NOT NULL DEFAULT 1 COMMENT '乐观锁版本号',
  `is_delete` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除: 0-未删除, 1-已删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_role_code`(`role_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '系统角色表' ROW_FORMAT = Dynamic;

