-- ----------------------------
-- Table structure for sup_sms_code
-- ----------------------------
DROP TABLE IF EXISTS `sup_sms_code`;
CREATE TABLE `sup_sms_code`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '手机号',
  `code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '验证码(6位数字)',
  `scene` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '使用场景:LOGIN(登录)/REGISTER(注册)/RESET_PWD(重置密码)/BIND_PHONE(绑定手机)',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'UNUSED' COMMENT '状态:UNUSED(未使用)/USED(已使用)/EXPIRED(已过期)',
  `expire_time` datetime NOT NULL COMMENT '过期时间(一般5-10分钟)',
  `ip_address` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '发送IP地址(防刷)',
  `used_time` datetime NULL DEFAULT NULL COMMENT '使用时间',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_phone_status`(`phone` ASC, `status` ASC) USING BTREE,
  INDEX `idx_expire_time`(`expire_time` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '短信验证码表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sup_sms_code
-- ----------------------------

-- ----------------------------
-- Table structure for sup_sys_parameter
-- ----------------------------
DROP TABLE IF EXISTS `sup_sys_parameter`;
CREATE TABLE `sup_sys_parameter`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `param_group` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '参数分组: SYSTEM/SWITCH/AI_RULE',
  `param_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '参数键',
  `param_value` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '参数值',
  `param_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'STRING' COMMENT '值类型: STRING/NUMBER/BOOLEAN/JSON',
  `param_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '参数中文名',
  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '参数说明',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '组内排序',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `create_id` bigint NOT NULL DEFAULT 0 COMMENT '创建人ID',
  `create_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '创建人名称',
  `modify_time` datetime NOT NULL COMMENT '修改时间',
  `modify_id` bigint NOT NULL DEFAULT 0 COMMENT '修改人ID',
  `modify_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '修改人名称',
  `ver` int NOT NULL DEFAULT 1 COMMENT '乐观锁版本号',
  `is_delete` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除: 0-未删除, 1-已删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_param_key`(`param_key` ASC) USING BTREE,
  INDEX `idx_param_group`(`param_group` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '系统参数表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sup_sys_parameter
-- ----------------------------
INSERT INTO `sup_sys_parameter` VALUES (1, 'SYSTEM', 'system_name', '招标文件AI编制工具', 'STRING', '系统名称', '系统显示名称', 1, '2026-04-15 09:34:09', 0, '', '2026-04-15 09:34:09', 0, '', 1, 0);
INSERT INTO `sup_sys_parameter` VALUES (2, 'SYSTEM', 'max_file_size_mb', '50', 'NUMBER', '最大文件大小(MB)', '上传文件大小限制，单位MB', 2, '2026-04-15 09:34:09', 0, '', '2026-04-15 09:34:09', 0, '', 1, 0);
INSERT INTO `sup_sys_parameter` VALUES (3, 'SYSTEM', 'session_timeout_min', '120', 'NUMBER', '会话超时时间(分钟)', '用户会话无操作超时时间', 3, '2026-04-15 09:34:09', 0, '', '2026-04-15 09:34:09', 0, '', 1, 0);
INSERT INTO `sup_sys_parameter` VALUES (4, 'SYSTEM', 'detection_fail_limit', '3', 'NUMBER', '检测不通过上限次数', '项目检测不通过的最大允许次数', 4, '2026-04-15 09:34:09', 0, '', '2026-04-15 09:34:09', 0, '', 1, 0);
INSERT INTO `sup_sys_parameter` VALUES (5, 'SWITCH', 'enable_ai_chat', 'true', 'BOOLEAN', '启用AI对话功能', '开启后用户可使用浮动AI对话组件', 1, '2026-04-15 09:34:09', 0, '', '2026-04-15 09:34:09', 0, '', 1, 0);
INSERT INTO `sup_sys_parameter` VALUES (6, 'SWITCH', 'enable_detection', 'true', 'BOOLEAN', '启用智能检测功能', '开启后系统将自动进行文档检测', 2, '2026-04-15 09:34:09', 0, '', '2026-04-15 09:34:09', 0, '', 1, 0);
INSERT INTO `sup_sys_parameter` VALUES (7, 'SWITCH', 'enable_notification', 'true', 'BOOLEAN', '启用消息通知', '开启后用户将收到系统消息通知', 3, '2026-04-15 09:34:09', 0, '', '2026-04-15 09:34:09', 0, '', 1, 0);
INSERT INTO `sup_sys_parameter` VALUES (8, 'AI_RULE', 'fairness_rules', '检查是否指定特定品牌或供应商，是否设置不合理门槛，是否存在地域限制等内容。', 'JSON', '公平竞争检测规则', 'AI公平竞争检测使用的规则文本', 1, '2026-04-15 09:34:09', 0, '', '2026-04-15 09:34:09', 0, '', 1, 0);
INSERT INTO `sup_sys_parameter` VALUES (9, 'AI_RULE', 'compliance_rules', '检查是否符合相关法律法规要求，是否符合招标文件格式规范，是否存在遗漏必要条款等内容。', 'JSON', '合规性检查规则', 'AI合规性检查使用的规则文本', 2, '2026-04-15 09:34:09', 0, '', '2026-04-15 09:34:09', 0, '', 1, 0);

-- ----------------------------
-- Table structure for sup_user
-- ----------------------------
DROP TABLE IF EXISTS `sup_user`;
CREATE TABLE `sup_user`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '用户ID',
  `username` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '用户名',
  `password` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '密码',
  `real_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '真实姓名',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '手机号',
  `email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '邮箱',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态: 0-禁用, 1-启用',
  `last_login_time` datetime NULL DEFAULT NULL COMMENT '最后登录时间',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `create_id` bigint NOT NULL DEFAULT 0 COMMENT '创建人ID',
  `create_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '创建人名称',
  `modify_time` datetime NOT NULL COMMENT '修改时间',
  `modify_id` bigint NOT NULL DEFAULT 0 COMMENT '修改人ID',
  `modify_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '修改人名称',
  `ver` int NOT NULL DEFAULT 1 COMMENT '乐观锁版本号',
  `is_delete` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除: 0-未删除, 1-已删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_username`(`username` ASC) USING BTREE,
  UNIQUE INDEX `idx_phone`(`phone` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '系统用户表' ROW_FORMAT = Dynamic;

